pages/account/orders/all:
---
customer:
    orders:
        limit: 8
---

{{#partial "page"}}
<div class="themevale_breadcrumb">
    {{> components/common/breadcrumbs breadcrumbs=breadcrumbs}}
    <h1 class="page-heading">{{lang 'account.orders.heading' }}</h1>
</div>
<main class="page">
    {{> components/account/navigation account_page='orders'}}

    <div class="account">
        <div class="account-head">
            {{#if customer.store_credit.value '>' 0}}
                <div class="alertBox alertBox--storeCredit">
                    {{{lang 'common.store_credit' store_credit=customer.store_credit.formatted}}}
                </div>
            {{/if}}
        </div>
        <div class="account-body">
            <section class="account-content">
                {{#if customer.orders.length}}
                    {{> components/account/orders-list orders=customer.orders}}
                    {{> components/common/small-paginator pagination.orders}}
                {{else}}
                    {{> components/common/alert-info (lang 'account.orders.none')}}
                {{/if}}
            </section>
        </div>
        {{{snippet 'account'}}}
    </div>
</main>

{{/partial}}
{{> layout/base}}

components/common/footer:
{{#if banners.bottom}}
    {{#if settings.data_tag_enabled}}
        <div class="banners" data-banner-location="bottom">
            {{#each (limit banners.bottom_metadata 1)}}
                <div class="banner" data-event-type="promotion" data-entity-id="{{this.id}}" data-name="{{this.banner-name}}" data-position="{{this.location}}" data-name="{{this.banner-name}}">
                    <div data-event-type="promotion-click">
                        {{{this.content}}}
                    </div>
                </div>
            {{/each}}
        </div>
    {{else}}
            <div class="banners" data-banner-location="bottom">
            <div class="banner">
                {{{limit banners.bottom 1}}}
            </div>
        </div>
    {{/if}}
{{/if}}
{{#if theme_settings.themevale_homepage_layout '===' 'homepage layout 1'}}
    {{> components/themevale/footer/footer-1}}
{{/if}}
{{#if theme_settings.themevale_homepage_layout '===' 'homepage layout 2'}}
    {{> components/themevale/footer/footer-2}}
{{/if}}
{{#if theme_settings.themevale_homepage_layout '===' 'homepage layout 3'}}
    {{> components/themevale/footer/footer-3}}
{{/if}}
{{#if theme_settings.themevale_BackTop}}
    <div id="back-to-top">
        <a href="javascript:void(0)">to top<svg class="icon"><use xlink:href="#icon-keyboard-arrow-down"></use></svg></a>
    </div>
{{/if}}

<script src="https://ajax.googleapis.com/ajax/libs/jquery/3.5.1/jquery.min.js"></script>
